export const DEFAULT_KNOWN_SOURCE_PATHS = [
  ...DEFAULT_HWK_SOURCE_PATHS,
  'source/your-chatbot-source.pdf',
];

export type UnknownSourcePolicy = 'exclude' | 'chatbot';

